"""Hydra-configurable evaluation loop for videos generated by video models."""

from __future__ import annotations

import logging
import random
import sys
import time
from pathlib import Path
from typing import Any

import numpy as np
import torch
from omegaconf import DictConfig, OmegaConf
from tqdm import tqdm

from .fvd import FVDMetric
from .io import (
    discover_video_pairs,
    pairing_report_to_jsonable,
    read_video,
    resize_video_to,
    resolve_video_dirs,
    safe_name,
)
from .metrics import (
    FIDMetric,
    LPIPSMetric,
    MetricSelection,
    aggregate_scalar_metrics,
    compute_psnr,
    compute_ssim,
)
from .serialization import append_jsonl, write_json

logger = logging.getLogger(__name__)


def _configure_logging(output_dir: Path, level: str, log_file: str | None) -> None:
    numeric_level = getattr(logging, level.upper(), logging.INFO)
    root = logging.getLogger()
    root.setLevel(numeric_level)

    formatter = logging.Formatter(
        "%(asctime)s %(levelname)s %(name)s: %(message)s"
    )

    if not any(isinstance(handler, logging.StreamHandler) for handler in root.handlers):
        stream_handler = logging.StreamHandler(sys.stdout)
        stream_handler.setFormatter(formatter)
        root.addHandler(stream_handler)

    if log_file:
        log_path = output_dir / log_file
        if not any(
            isinstance(handler, logging.FileHandler)
            and Path(handler.baseFilename) == log_path
            for handler in root.handlers
        ):
            file_handler = logging.FileHandler(log_path)
            file_handler.setFormatter(formatter)
            root.addHandler(file_handler)


def _resolve_device(device_cfg: str) -> torch.device:
    if device_cfg == "auto":
        return torch.device("cuda" if torch.cuda.is_available() else "cpu")
    return torch.device(device_cfg)


def _optional_int(value: Any) -> int | None:
    if value is None:
        return None
    return int(value)


def _set_seed(seed: int | None) -> None:
    if seed is None:
        return
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def _run_or_record_error(
    metric_name: str,
    errors: dict[str, str],
    continue_on_metric_error: bool,
    fn,
):
    try:
        return fn()
    except Exception as exc:
        errors[metric_name] = str(exc)
        logger.exception("Metric '%s' failed", metric_name)
        if not continue_on_metric_error:
            raise
        return None


def _validate_and_prepare_pair(
    *,
    gt_video: np.ndarray,
    generated_video: np.ndarray,
    pair_name: str,
    cfg: DictConfig,
) -> tuple[np.ndarray | None, np.ndarray | None, dict[str, Any]]:
    record: dict[str, Any] = {
        "name": pair_name,
        "gt_num_frames": int(gt_video.shape[0]),
        "generated_num_frames": int(generated_video.shape[0]),
        "gt_shape": list(gt_video.shape),
        "generated_shape": list(generated_video.shape),
    }

    if gt_video.shape[0] != generated_video.shape[0]:
        message = (
            f"Frame-count mismatch for {pair_name}: "
            f"gt={gt_video.shape[0]}, generated={generated_video.shape[0]}"
        )
        record["status"] = "frame_mismatch"
        record["error"] = message
        logger.warning(message)
        if cfg.strict.fail_on_frame_mismatch:
            raise ValueError(message)
        if cfg.strict.require_equal_frames:
            return None, None, record

        target_frames = min(gt_video.shape[0], generated_video.shape[0])
        gt_video = gt_video[:target_frames]
        generated_video = generated_video[:target_frames]
        record["truncated_num_frames"] = int(target_frames)

    gt_hw = gt_video.shape[1:3]
    generated_hw = generated_video.shape[1:3]
    if gt_hw != generated_hw:
        message = (
            f"Resolution mismatch for {pair_name}: "
            f"gt={gt_hw}, generated={generated_hw}"
        )
        record["resolution_warning"] = message
        if cfg.strict.require_equal_resolution:
            record["status"] = "resolution_mismatch"
            record["error"] = message
            logger.warning(message)
            return None, None, record

        logger.warning("%s; resizing generated video to GT resolution", message)
        generated_video = resize_video_to(generated_video, gt_hw)
        record["generated_resized_to"] = list(gt_hw)

    skip = int(cfg.skip_first_n_frames)
    if skip > 0:
        gt_video = gt_video[skip:]
        generated_video = generated_video[skip:]
        record["skipped_initial_frames"] = skip

    if gt_video.shape[0] == 0:
        record["status"] = "empty_after_skip"
        record["error"] = (
            f"No frames left for {pair_name} after skipping {skip} frame(s)"
        )
        return None, None, record

    record["evaluated_num_frames"] = int(gt_video.shape[0])
    record["evaluated_shape"] = list(gt_video.shape)
    return gt_video, generated_video, record


def evaluate_from_config(cfg: DictConfig) -> dict[str, Any]:
    """Run evaluation from a Hydra/OmegaConf config."""

    output_dir = Path(str(cfg.output_dir)).expanduser().resolve()
    output_dir.mkdir(parents=True, exist_ok=True)
    _configure_logging(output_dir, str(cfg.logging.level), str(cfg.logging.log_file))

    resolved_cfg_path = output_dir / "config_resolved.yaml"
    OmegaConf.save(config=cfg, f=resolved_cfg_path)

    _set_seed(None if cfg.seed is None else int(cfg.seed))
    device = _resolve_device(str(cfg.device))
    selection = MetricSelection.from_config(cfg.metrics)
    logger.info("Using device: %s", device)
    logger.info("Selected metrics: %s", sorted(selection.names))

    gt_dir, generated_dir = resolve_video_dirs(
        cfg.input_dir,
        cfg.gt_dir,
        cfg.generated_dir,
        str(cfg.gt_subdir),
        str(cfg.generated_subdir),
    )
    pairing_report = discover_video_pairs(
        gt_dir,
        generated_dir,
        pattern=str(cfg.video_glob),
        gt_suffixes=list(cfg.pairing.gt_suffixes),
        generated_suffixes=list(cfg.pairing.generated_suffixes),
        case_sensitive=bool(cfg.pairing.case_sensitive),
        max_videos=None if cfg.max_videos is None else int(cfg.max_videos),
        fail_on_missing_pairs=bool(cfg.strict.fail_on_missing_pairs),
    )

    write_json(output_dir / "pairing_report.json", pairing_report_to_jsonable(pairing_report))

    per_video_dir = output_dir / "per_video"
    jsonl_path = output_dir / "per_video_metrics.jsonl"
    if jsonl_path.exists():
        jsonl_path.unlink()

    metric_errors: dict[str, str] = {}
    continue_on_metric_error = bool(cfg.continue_on_metric_error)

    lpips_metric = None
    fid_metric = None
    fvd_metric = None

    if selection.wants("lpips"):
        lpips_metric = _run_or_record_error(
            "lpips_init",
            metric_errors,
            continue_on_metric_error,
            lambda: LPIPSMetric(device=device, net=str(cfg.lpips.net)),
        )
    if selection.wants("fid"):
        fid_metric = _run_or_record_error(
            "fid_init",
            metric_errors,
            continue_on_metric_error,
            lambda: FIDMetric(device=device),
        )
    if selection.wants("fvd"):
        fvd_metric = _run_or_record_error(
            "fvd_init",
            metric_errors,
            continue_on_metric_error,
            lambda: FVDMetric(device=device, target_len=_optional_int(cfg.fvd.target_len)),
        )

    valid_gt_videos: list[np.ndarray] = []
    valid_generated_videos: list[np.ndarray] = []
    per_video_metrics: list[dict[str, Any]] = []
    skipped_records: list[dict[str, Any]] = []

    start_time = time.time()
    for pair in tqdm(pairing_report.pairs, desc="Evaluating videos"):
        pair_record: dict[str, Any] = {
            "name": pair.name,
            "gt_path": str(pair.gt_path),
            "generated_path": str(pair.generated_path),
        }

        try:
            gt_raw = read_video(pair.gt_path)
            generated_raw = read_video(pair.generated_path)
            gt_video, generated_video, validation = _validate_and_prepare_pair(
                gt_video=gt_raw,
                generated_video=generated_raw,
                pair_name=pair.name,
                cfg=cfg,
            )
            pair_record.update(validation)
        except Exception as exc:
            pair_record["status"] = "read_or_validation_error"
            pair_record["error"] = str(exc)
            logger.exception("Failed to read or validate pair '%s'", pair.name)
            skipped_records.append(pair_record)
            append_jsonl(jsonl_path, pair_record)
            if bool(cfg.strict.fail_on_video_error):
                raise
            continue

        if gt_video is None or generated_video is None:
            skipped_records.append(pair_record)
            append_jsonl(jsonl_path, pair_record)
            write_json(per_video_dir / f"{safe_name(pair.name)}.json", pair_record)
            continue

        metrics: dict[str, Any] = {}
        if selection.wants("psnr") or selection.wants("mse"):
            metrics.update(compute_psnr(gt_video, generated_video, per_frame=True))
        if selection.wants("ssim"):
            result = _run_or_record_error(
                f"{pair.name}:ssim",
                metric_errors,
                continue_on_metric_error,
                lambda: compute_ssim(gt_video, generated_video, per_frame=True),
            )
            if result:
                metrics.update(result)
        if selection.wants("lpips") and lpips_metric is not None:
            result = _run_or_record_error(
                f"{pair.name}:lpips",
                metric_errors,
                continue_on_metric_error,
                lambda: lpips_metric.compute(
                    gt_video,
                    generated_video,
                    batch_size=int(cfg.batch_size.lpips),
                    per_frame=True,
                ),
            )
            if result:
                metrics.update(result)

        pair_record["status"] = "ok"
        pair_record["metrics"] = metrics
        per_video_metrics.append(metrics)
        valid_gt_videos.append(gt_video)
        valid_generated_videos.append(generated_video)

        append_jsonl(jsonl_path, pair_record)
        write_json(per_video_dir / f"{safe_name(pair.name)}.json", pair_record)

    distribution_metrics: dict[str, Any] = {}
    if selection.wants("fid") and fid_metric is not None and valid_gt_videos:
        result = _run_or_record_error(
            "fid",
            metric_errors,
            continue_on_metric_error,
            lambda: fid_metric.compute(
                valid_gt_videos,
                valid_generated_videos,
                batch_size=int(cfg.batch_size.fid),
            ),
        )
        if result is not None:
            distribution_metrics["fid"] = float(result)

    if selection.wants("fvd") and fvd_metric is not None and valid_gt_videos:
        result = _run_or_record_error(
            "fvd",
            metric_errors,
            continue_on_metric_error,
            lambda: fvd_metric.compute(
                valid_gt_videos,
                valid_generated_videos,
                batch_size=int(cfg.batch_size.fvd),
            ),
        )
        if result is not None:
            distribution_metrics["fvd"] = float(result)

    summary = {
        "input_dir": str(Path(str(cfg.input_dir)).expanduser().resolve()),
        "gt_dir": str(gt_dir),
        "generated_dir": str(generated_dir),
        "output_dir": str(output_dir),
        "metrics": sorted(selection.names),
        "num_pairs_discovered": len(pairing_report.pairs),
        "num_videos_evaluated": len(valid_gt_videos),
        "num_videos_skipped": len(skipped_records),
        "num_missing_generated": len(pairing_report.missing_generated),
        "num_missing_gt": len(pairing_report.missing_gt),
        "scalar_metrics": aggregate_scalar_metrics(per_video_metrics),
        "distribution_metrics": distribution_metrics,
        "metric_errors": metric_errors,
        "elapsed_seconds": time.time() - start_time,
        "per_video_metrics_jsonl": str(jsonl_path),
        "pairing_report": str(output_dir / "pairing_report.json"),
    }

    write_json(output_dir / "summary.json", summary)
    write_json(output_dir / "skipped_videos.json", skipped_records)

    logger.info("Evaluated %d video pair(s)", len(valid_gt_videos))
    logger.info("Skipped %d video pair(s)", len(skipped_records))
    logger.info("Summary written to %s", output_dir / "summary.json")
    for name, value in distribution_metrics.items():
        logger.info("%s: %.6f", name.upper(), value)

    return summary
